UPM = 2048


class Face:
    def __init__(self, adv, kern): self.adv, self.kern = adv, kern

    def getlength(self, s):  # font units at size UPM
        return sum(self.adv[c] for c in s) + sum(self.kern.get(s[i:i + 2], 0) for i in range(len(s) - 1))


R, B = Face(REGULAR, REGULAR_KERN), Face(BOLD, BOLD_KERN)


def w(s, f=R, px=14, ls=0.0):
    """Width in px of s at px size, plus letter-spacing ls (em) per character."""
    return f.getlength(s) / UPM * px + ls * px * len(s)
